const assert = require('assert');
const { LineNumberStream } = require('./linenumber.js');

function run(chunks) {
  return new Promise((resolve, reject) => {
    const s = new LineNumberStream();
    let out = '';
    s.on('data', (d) => { out += d.toString(); });
    s.on('end', () => resolve(out));
    s.on('error', reject);
    for (const c of chunks) s.write(c);
    s.end();
  });
}

(async () => {
  assert.strictEqual(await run(['alpha\nbeta\n']), '1: alpha\n2: beta\n');
  // chunk boundary in the middle of a line
  assert.strictEqual(await run(['al', 'pha\nbe', 'ta\n']), '1: alpha\n2: beta\n',
    'partial lines across chunks must be buffered');
  // final line without trailing newline must still be emitted
  const out = await run(['one\ntwo']);
  assert.ok(out.startsWith('1: one\n'), out);
  assert.ok(out.includes('2: two'), 'unterminated final line must be flushed');
  assert.strictEqual(await run([]), '');
  console.log('PASS');
})().catch((e) => { console.error(e); process.exit(1); });

