const { Transform } = require('stream');

class LineNumberStream extends Transform {
  constructor(options) {
    super(options);
    this._buffer = '';
    this._line = 0;
  }

  _transform(chunk, encoding, callback) {
    this._buffer += chunk.toString('utf8');
    const parts = this._buffer.split('\n');
    this._buffer = parts.pop();
    for (const line of parts) {
      this._line += 1;
      this.push(`${this._line}: ${line}\n`);
    }
    callback();
  }

  _flush(callback) {
    if (this._buffer.length > 0) {
      this._line += 1;
      this.push(`${this._line}: ${this._buffer}\n`);
    }
    callback();
  }
}

module.exports = { LineNumberStream };

